method get_max_triples(n: int) returns (count: int)
    requires n > 0
    ensures count >= 0
    ensures count == CountValidTriples(n)

    // Helper function to calculate the value of a[i]
    function a(i: int): int
        requires 1 <= i <= n
        ensures a(i) == i * i - i + 1
    {
        return i * i - i + 1;
    }

    // Helper function to count valid triples
    function CountValidTriples(n: int): int
        requires n > 0
        ensures 0 <= result <= (n * (n - 1) * (n - 2)) / 6
    {
        var count := 0;
        // Iterate through all possible triples (i, j, k)
        var i := 1;
        while i <= n - 2
            invariant 1 <= i <= n - 1
            invariant count >= 0
        {
            var j := i + 1;
            while j <= n - 1
                invariant i < j <= n
                invariant count >= 0
            {
                var k := j + 1;
                while k <= n
                    invariant j < k <= n
                    invariant count >= 0
                {
                    if (a(i) + a(j) + a(k)) % 3 == 0 {
                        count := count + 1;
                    }
                    k := k + 1;
                }
                j := j + 1;
            }
            i := i + 1;
        }
        return count;
    }
